import { ReactNode } from 'react';
/**
 * Controls which direction a panel opens relative to its anchor element.
 *
 * ```
 *                  top-start       top-end
 *                  ┌─────────┐    ┌─────────┐
 *                  │  Panel  │    │  Panel  │
 *                  └────┬────┘    └────┬────┘
 *                       │              │
 *  left-start ┌───┐   ┌──────────────────┐   ┌───┐ right-start
 *             │   │───│  Anchor Element  │───│   │
 *  left-end   └───┘   └──────────────────┘   └───┘ right-end
 *                       │              │
 *                  ┌────┴────┐    ┌────┴────┐
 *                  │  Panel  │    │  Panel  │
 *                  └─────────┘    └─────────┘
 *                bottom-start    bottom-end
 * ```
 *
 * - `start` means aligned to the top or left edge of the anchor
 * - `end` means aligned to the bottom or right edge of the anchor
 */
export type Placement = 'bottom-start' | 'bottom-end' | 'top-start' | 'top-end' | 'right-start' | 'right-end' | 'left-start' | 'left-end';
/**
 * Shared menu option interface used by both SingleSelectPanel and MultiSelectPanel.
 * Single source of truth — prevents type drift between components.
 */
export interface BaseMenuOption {
    /** Unique identifier for the option */
    id: string;
    /** Display label for the option */
    label: string;
    /** Optional icon to display with the option */
    icon?: ReactNode;
    /** Whether this option is disabled */
    disabled?: boolean;
    /** Additional information about this option (shown in popover with info icon when hovered) */
    popover?: ReactNode | string;
    /** Whether this option is a section header */
    isHeader?: boolean;
}
